import{_ as a,o as e,c as d,ag as r}from"./chunks/framework.CvZZEx4j.js";const p=JSON.parse('{"title":"加强模式","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/enhanced-mode.md","filePath":"advanced/enhanced-mode.md","lastUpdated":null}'),l={name:"advanced/enhanced-mode.md"};function o(n,t,i,s,h,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="加强模式" tabindex="-1">加强模式 <a class="header-anchor" href="#加强模式" aria-label="Permalink to &quot;加强模式&quot;">​</a></h1><h2 id="什么是加强模式" tabindex="-1">什么是加强模式 <a class="header-anchor" href="#什么是加强模式" aria-label="Permalink to &quot;什么是加强模式&quot;">​</a></h2><p>加强模式（Enhanced Mode）是为了解决 <strong>AI 不能稳定输出 Galgame 格式</strong> 的问题而设计的。</p><p>正常情况下，AI 需要同时完成两件事：</p><ol><li>创作故事内容</li><li>按 Galgame 标签格式输出</li></ol><p>部分模型在这两件事之间顾此失彼。加强模式将它们拆分为 <strong>两次生成</strong>：</p><table tabindex="0"><thead><tr><th>步骤</th><th>任务</th></tr></thead><tbody><tr><td><strong>第一次生成</strong></td><td>AI 专注于创作故事内容（可以不遵循格式）</td></tr><tr><td><strong>第二次生成</strong></td><td>插件自动将故事内容发给 AI，要求格式化为 Galgame 标签</td></tr></tbody></table><h2 id="启用加强模式" tabindex="-1">启用加强模式 <a class="header-anchor" href="#启用加强模式" aria-label="Permalink to &quot;启用加强模式&quot;">​</a></h2><ol><li>打开 <strong>设置面板</strong></li><li>找到「加强模式」开关</li><li>开启后，配置第二次生成使用的设置档</li></ol><h2 id="配置项" tabindex="-1">配置项 <a class="header-anchor" href="#配置项" aria-label="Permalink to &quot;配置项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>说明</th></tr></thead><tbody><tr><td><strong>Preset</strong></td><td>第二次生成使用的采样预设</td></tr><tr><td><strong>Profile</strong></td><td>第二次生成使用的 API 配置档</td></tr><tr><td><strong>Model</strong></td><td>第二次生成使用的模型（可选不同的格式化专用模型）</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">推荐</p><p>第二次生成可以使用较便宜/较快的模型，因为它只需要做格式化，不需要创作能力。</p></div><h2 id="使用流程" tabindex="-1">使用流程 <a class="header-anchor" href="#使用流程" aria-label="Permalink to &quot;使用流程&quot;">​</a></h2><ol><li>开启加强模式</li><li>正常发送消息</li><li>AI 先完成第一次生成（内容创作）</li><li>插件自动触发第二次生成（格式化）</li><li>覆盖层上会有进度提示</li><li>最终以 Galgame 格式展示结果</li></ol>',14)])])}const b=a(l,[["render",o]]);export{p as __pageData,b as default};
